package factory;

import java.util.Random;

/**
 * Creates employees with random personal details and salaries within the
 * assignment's inclusive salary range. IDs are assigned sequentially so they
 * remain unique within each generated array.
 */
public class EmployeeGenerator {

    /** Number of employees generated by the no-argument method. */
    public static final int NUM_EMPLOYEES = 10000;
    /** Lowest salary generated, in NIS. */
    public static final int MIN_SALARY = 3000;
    /** Highest salary generated, in NIS. */
    public static final int MAX_SALARY = 15000;

    /** First ID in each generated employee sequence. */
    public static final int FIRST_ID = 100000000;

    /** Source values used when choosing generated first names. */
    private static final String[] FIRST_NAMES = {
            "Daniel", "Noa", "Itay", "Maya", "Yossi", "Ronit", "Omer", "Yael",
            "Avi", "Shira", "Eitan", "Tamar", "Gal", "Lior", "Dana", "Roni"
    };

    /** Source values used when choosing generated last names. */
    private static final String[] LAST_NAMES = {
            "Cohen", "Levi", "Mizrachi", "Peretz", "Biton", "Dahan", "Avraham",
            "Friedman", "Katz", "Azulay", "Shapiro", "Ben David"
    };

    /** Source values used when building generated addresses. */
    private static final String[] CITIES = {
            "Tel Aviv", "Jerusalem", "Haifa", "Ashdod", "Beer Sheva", "Gedera",
            "Rishon LeZion", "Netanya", "Holon", "Petah Tikva"
    };

    /** Source values used when building generated addresses. */
    private static final String[] STREETS = {
            "Herzl", "Rothschild", "Ben Gurion", "Weizmann", "Jabotinsky",
            "HaNasi", "Allenby", "Dizengoff", "Bialik", "HaPalmach"
    };

    /** Shared random source for generated employee attributes. */
    private static final Random RANDOM = new Random();

    private EmployeeGenerator() {
        // utility class
    }

    /**
     * Generates {@value #NUM_EMPLOYEES} employees.
     *
     * @return an array of generated employees
     */
    public static Employee[] generateEmployees() {
        return generateEmployees(NUM_EMPLOYEES);
    }

    /**
     * Generates the requested number of employees with random details.
     *
     * IDs increase by one starting at {@link #FIRST_ID}; salaries include
     * both {@link #MIN_SALARY} and {@link #MAX_SALARY} as possible values.
     *
     * @param count number of employees to create
     * @return an array containing {@code count} employees
     * @throws IllegalArgumentException if {@code count} is negative
     */
    public static Employee[] generateEmployees(int count) {
        if (count < 0) {
            throw new IllegalArgumentException("count must not be negative: " + count);
        }

        Employee[] employees = new Employee[count];

        for (int i = 0; i < count; i++) {
            // Use the array index to make IDs predictable and unique.
            int id = FIRST_ID + i;
            String firstName = pickRandom(FIRST_NAMES);
            String lastName = pickRandom(LAST_NAMES);
            // Include the unique ID in the email so generated addresses do not collide.
            String email = firstName.toLowerCase() + "." + lastName.toLowerCase().replace(" ", "")
                    + id + "@factory.co.il";
            String phone = "05" + RANDOM.nextInt(10) + "-" + (1000000 + RANDOM.nextInt(9000000));
            String address = pickRandom(STREETS) + " " + (1 + RANDOM.nextInt(150))
                    + ", " + pickRandom(CITIES);
            // Add one to the random bound so MAX_SALARY can be generated too.
            int salary = MIN_SALARY + RANDOM.nextInt(MAX_SALARY - MIN_SALARY + 1);

            employees[i] = new Employee(id, firstName, lastName, email, phone, address, salary);
        }

        return employees;
    }

    /**
     * Chooses one value from a non-empty source array.
     *
     * @param pool available values
     * @return one randomly selected value
     */
    private static String pickRandom(String[] pool) {
        return pool[RANDOM.nextInt(pool.length)];
    }
}
